def enhance(pages):
    for slug, document in list(pages.items()):
        if 'src/site.js' not in document: continue
        document=re.sub(r'<header class="site-header"[\s\S]*?</header>', HEADER, document, count=1)
        # Keep a discoverable newsletter entry in the footer on every experience.
        document=document.replace('<div class="footer-bottom">','<div class="footer-utilities"><button class="text-button micro" data-open="newsletter-dialog">Receive our correspondence →</button><button class="text-button micro" data-preferences>Your preferences</button><button class="text-button micro" data-open="contact-dialog">Contact us</button></div><div class="footer-bottom">')
        document=document.replace('<a href="employees.html">Employees</a>','<a href="employees.html">Associates</a>')
        if slug=='investors':
            document=re.sub(r'<section id="investor-gate"[\s\S]*?</section>', '', document, count=1)
            document=document.replace('<div id="investor-content" hidden>','<div id="investor-content">')
        if slug=='employee-create':
            document=document.replace('<button class="button" type="submit">Create account</button>', '<fieldset class="signup-preference"><legend>A preference is requested.</legend><p>You may opt in. You may opt out.</p><label><input type="radio" name="signup-opportunity" value="in"/> Opt in</label><label><input type="radio" name="signup-opportunity" value="out"/> Opt out</label><p class="demo-note">Optional concept. No action or enrollment is attached to either choice.</p></fieldset><button class="button" type="submit">Create account</button>')
        if slug=='legacy-match':
            items=['Your loyalty','Your discretion','Your need for sleep','Your memory of previous employers','Your attachment to your current life','Your opinions, generally','Your sense of where you end and the company begins','Your will']
            scale=['Strong','Somewhat strong','Neutral','Somewhat weak','Weak']
            intro='''<div id="assessment-intro"><p>LegacyMatch is our AI-guided personality assessment. It learns who you are, so we can find where you fit. There are no right or wrong answers. There are, however, answers.</p><p class="demo-note">Eight questions. One placement. Local demonstration; responses and response times are not collected.</p><button class="button" id="assessment-begin">Begin assessment <span aria-hidden="true">→</span></button></div>'''
            quiz='<form id="assessment" class="stepped-assessment" hidden><div class="step-meta"><span id="assessment-step-label" class="micro" role="status">Question 1 of 8</span><span class="micro">LegacyMatch™</span></div><progress id="assessment-progress" max="8" value="1" aria-label="Assessment progress"></progress>'
            for i,item in enumerate(items):
                quiz+=f'<fieldset class="quiz-step" data-step="{i}" {"hidden" if i else ""}><legend>{i+1:02d} / {item}</legend><p>Rate from Strong to Weak. Answer quickly and honestly.</p><div class="step-choices">'+''.join(f'<label><input type="radio" name="item-{i}" value="{j}"/><span>{value}</span></label>' for j,value in enumerate(scale))+'</div></fieldset>'
            quiz+='''<p id="assessment-error" role="alert"></p><div class="step-actions"><button class="button secondary" id="assessment-back" type="button">Back</button><button class="button" id="assessment-next" type="button">Continue →</button></div></form><section id="assessment-review" hidden><p class="micro">Assessment complete / Review</p><h2>Your responses are in order.</h2><p>Congratulations. You are a Perpetuity Associate (IC2).</p><p>Ideal placement: Correspondent, PO Box (on-site).<br/>Strongest trait: Availability.<br/>Area for growth: Everything else.</p><p>The next step is standard issue.</p><p class="demo-note">Submitting opens the demonstration store. Nothing is shared, scheduled, or purchased.</p><div class="action-row"><button class="button secondary" id="assessment-edit">Review answers</button><button class="button" id="assessment-submit">Submit &amp; enter the store →</button></div></section><section id="assessment-processing" hidden aria-live="polite"><p class="micro">LegacyMatch™ / Processing</p><h2>Reconciling the two…</h2><p>Locating your family. Preparing standard issue.</p></section>'''
            document=re.sub(r'<div class="reading">[\s\S]*?</main>', '<div class="reading assessment-reading">'+intro+quiz+'</div></main>', document,count=1)
        if slug=='contact':
            body='''<section class="page-heading"><p class="micro">Office of Correspondence</p><h1>At your service.<br/>In perpetuity.</h1><p class="lede">A point of contact for every relationship.</p></section><section class="contact-grid"><article><p class="micro">01 / Switchboard</p><h2>A considered reception.</h2><p>Our answering line will direct you to the appropriate part of the system.</p><p class="contact-placeholder">Telephone number to be assigned.</p><button class="button secondary" data-open="phone-dialog">Preview answering line →</button></article><article><p class="micro">02 / Media</p><h2>For the record.</h2><p>Press inquiries are handled by Mind Control Press.</p><p class="contact-placeholder">Media address to be assigned.</p><button class="text-button micro" data-open="contact-dialog">Contact information →</button></article><article><p class="micro">03 / Investors</p><h2>A longer conversation.</h2><p>Capital, allocation, and matters of continuity.</p><a class="section-link micro" href="investor-relations.html">Investor Relations →</a></article></section><section class="correspondence-strip"><p>Written correspondence remains welcome.<br/><small>Office of Correspondence · PO Box 1000 · [Jurisdiction Withheld]</small></p><button class="text-button micro" data-open="contact-dialog">All contact information →</button></section>'''
            document=re.sub(r'<main id="main">[\s\S]*?</main>', '<main id="main">'+body+'</main>',document,count=1)
        document=document.replace('The investor access selection is stored only for this tab’s session;', 'Audience, investor status, and concept preferences are stored only for this tab’s session;')
        document=document.replace('</body>',DIALOGS+'<script type="module" src="/src/experiences.js"></script></body>')
        pages[slug]=document
